#!/usr/bin/env node
// Brand assets from brand/tokens.json (docs/BRAND.md): the logo SVGs, the web colour variables,
// the favicon and the Android launcher icons. Run it after changing the brand:
//
//   node scripts/brand.mjs            write every generated file
//   node scripts/brand.mjs --check    fail if any generated file is out of date (CI)
//   node scripts/brand.mjs --png      also render the iOS app icon (needs Edge or Chrome)
//
// The app's own colours live in core/ui Tokens.kt; BrandTokensTest checks they match.
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const brand = JSON.parse(readFileSync(join(root, "brand/tokens.json"), "utf8"));
const { light, dark } = brand.colors;
const L = brand.logo;
const header = (comment) => comment.replace("%", "Generated by scripts/brand.mjs from brand/tokens.json: do not edit.");

// ── Logo ──────────────────────────────────────────────────────────────────────
const n = (v) => Number(v.toFixed(3)).toString();
/** Eyes and beak on the 24 grid, scaled by [s] and moved by [dx], [dy]; [beak] colour or null to skip. */
function face(s, dx, dy, ring, beak) {
  const eye = (cx) =>
    `<circle cx="${n(dx + cx * s)}" cy="${n(dy + L.eyeY * s)}" r="${n(L.eyeRadius * s)}" fill="none" stroke="${ring}" stroke-width="${n(L.ringStroke * s)}"/>`;
  const b = `<path d="M${n(dx + L.beakLeft * s)} ${n(dy + L.beakTop * s)}H${n(dx + L.beakRight * s)}L${n(dx + (L.grid / 2) * s)} ${n(dy + L.beakTip * s)}Z" fill="${beak}"/>`;
  return eye(L.leftEyeX) + eye(L.rightEyeX) + b;
}
const svg = (size, body, title) =>
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}"${title ? ` role="img" aria-label="${title}"` : ""}>${body}</svg>\n`;
/** The logo as OwlsplitLogo draws it: rounded square. */
const logoSvg = svg(L.grid, `<rect width="${L.grid}" height="${L.grid}" rx="${L.corner}" fill="${light.accent}"/>` + face(1, 0, 0, "#FFFFFF", light.brandBeak), "Owlsplit");
/** Full-bleed square for stores and iOS, which round the corners themselves. */
const iconSvg = svg(L.grid, `<rect width="${L.grid}" height="${L.grid}" fill="${light.accent}"/>` + face(1, 0, 0, "#FFFFFF", light.brandBeak));

// ── Web ───────────────────────────────────────────────────────────────────────
const kebab = (k) => k.replace(/[A-Z]/g, (c) => "-" + c.toLowerCase());
const vars = (colors) => Object.entries(colors).map(([k, v]) => `  --os-${kebab(k)}: ${v};`).join("\n");
const css = `${header("/* % */")}
:root {
${vars(light)}
}
@media (prefers-color-scheme: dark) {
  :root {
${vars(dark).replace(/^/gm, "  ")}
  }
}
`;

// ── Android launcher icon ─────────────────────────────────────────────────────
// Adaptive icons are 108 dp with a 66 dp safe circle: the 24-unit logo grid is drawn as a 72 dp
// square in the middle (scale 3), which keeps the eyes and beak inside the safe zone.
const circlePath = (cx, cy, r) => `M${n(cx - r)},${n(cy)} a${n(r)},${n(r)} 0 1,0 ${n(2 * r)},0 a${n(r)},${n(r)} 0 1,0 ${n(-2 * r)},0`;
function vectorFace(viewport, s, d, eyeColor, beakColor) {
  const eye = (cx) => `    <path
        android:pathData="${circlePath(d + cx * s, d + L.eyeY * s, L.eyeRadius * s)}"
        android:strokeColor="${eyeColor}"
        android:strokeWidth="${n(L.ringStroke * s)}" />`;
  const beak = `    <path
        android:fillColor="${beakColor}"
        android:pathData="M${n(d + L.beakLeft * s)},${n(d + L.beakTop * s)} L${n(d + L.beakRight * s)},${n(d + L.beakTop * s)} L${n(d + (L.grid / 2) * s)},${n(d + L.beakTip * s)} Z" />`;
  return `${eye(L.leftEyeX)}\n${eye(L.rightEyeX)}\n${beak}`;
}
const vector = (size, viewport, body) => `<?xml version="1.0" encoding="utf-8"?>
${header("<!-- % -->")}
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="${size}dp"
    android:height="${size}dp"
    android:viewportWidth="${viewport}"
    android:viewportHeight="${viewport}">
${body}
</vector>
`;
const foreground = vector(108, 108, vectorFace(108, 3, 18, "#FFFFFFFF", "#FF" + light.brandBeak.slice(1)));
// Themed icons (Android 13+): one colour, the launcher tints it.
const monochrome = vector(108, 108, vectorFace(108, 3, 18, "#FFFFFFFF", "#FFFFFFFF"));
// Android 7 has no adaptive icons: the rounded logo itself, 48 dp.
const legacy = vector(48, L.grid, `    <path
        android:fillColor="#FF${light.accent.slice(1)}"
        android:pathData="M${L.corner},0 H${L.grid - L.corner} A${L.corner},${L.corner} 0 0 1 ${L.grid},${L.corner} V${L.grid - L.corner} A${L.corner},${L.corner} 0 0 1 ${L.grid - L.corner},${L.grid} H${L.corner} A${L.corner},${L.corner} 0 0 1 0,${L.grid - L.corner} V${L.corner} A${L.corner},${L.corner} 0 0 1 ${L.corner},0 Z" />
${vectorFace(L.grid, 1, 0, "#FFFFFFFF", "#FF" + light.brandBeak.slice(1))}`);
const adaptive = `<?xml version="1.0" encoding="utf-8"?>
${header("<!-- % -->")}
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="@color/ic_launcher_background" />
    <foreground android:drawable="@drawable/ic_launcher_foreground" />
    <monochrome android:drawable="@drawable/ic_launcher_monochrome" />
</adaptive-icon>
`;
const colors = `<?xml version="1.0" encoding="utf-8"?>
${header("<!-- % -->")}
<resources>
    <color name="ic_launcher_background">${light.accent}</color>
</resources>
`;

const res = "composeApp/src/androidMain/res";
const files = {
  "brand/logo.svg": logoSvg,
  "brand/icon.svg": iconSvg,
  "firebase/hosting/brand.css": css,
  "firebase/hosting/favicon.svg": logoSvg,
  [`${res}/drawable/ic_launcher_foreground.xml`]: foreground,
  [`${res}/drawable/ic_launcher_monochrome.xml`]: monochrome,
  [`${res}/mipmap/ic_launcher.xml`]: legacy,
  [`${res}/mipmap-anydpi-v26/ic_launcher.xml`]: adaptive,
  [`${res}/values/ic_launcher_colors.xml`]: colors,
};

const check = process.argv.includes("--check");
const stale = [];
for (const [path, content] of Object.entries(files)) {
  const file = join(root, path);
  const current = existsSync(file) ? readFileSync(file, "utf8") : null;
  if (current === content) continue;
  if (check) {
    stale.push(path);
  } else {
    mkdirSync(dirname(file), { recursive: true });
    writeFileSync(file, content);
    console.log("wrote", path);
  }
}
if (check) {
  if (stale.length) {
    console.error("Brand files out of date (run `node scripts/brand.mjs`):\n  " + stale.join("\n  "));
    process.exit(1);
  }
  console.log("Brand files up to date");
}

// ── iOS app icon (PNG, 1024 px, opaque) ───────────────────────────────────────
if (process.argv.includes("--png")) {
  const browsers = [
    "C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe",
    "C:/Program Files/Google/Chrome/Application/chrome.exe",
    "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
    "/usr/bin/google-chrome",
    "/usr/bin/chromium",
  ];
  const browser = browsers.find(existsSync);
  if (!browser) throw new Error("No Edge or Chrome found to render the PNG");
  const page = join(tmpdir(), "owlsplit-icon.html");
  writeFileSync(page, `<!doctype html><html><body style="margin:0">${iconSvg.replace("<svg ", '<svg width="1024" height="1024" ')}</body></html>`);
  const out = join(root, "iosApp/iosApp/Assets.xcassets/AppIcon.appiconset/AppIcon.png");
  mkdirSync(dirname(out), { recursive: true });
  execFileSync(browser, ["--headless=new", "--disable-gpu", "--hide-scrollbars", "--force-device-scale-factor=1",
    "--window-size=1024,1024", `--screenshot=${out}`, "file:///" + page.replace(/\\/g, "/")], { stdio: "ignore" });
  rmSync(page);
  console.log("wrote iosApp/iosApp/Assets.xcassets/AppIcon.appiconset/AppIcon.png");
}
